  const permisosAdministrador=['proveedores.ver','proveedores.editar','proveedores.listado','proveedores.nuevo','proveedores.modificar','proveedores.catalogos','catalogos.ver','catalogos.editar','catalogos.productos','catalogos.nuevo','cotizaciones.ver','cotizaciones.editar','cotizaciones.nueva','cotizaciones.comprar','cotizaciones.historial','pedidos.ver','pedidos.editar','usuarios.ver','usuarios.editar','usuarios.acceder','usuarios.listado','usuarios.crear','usuarios.roles','configuracion.almacenes','configuracion.tipos','configuracion.marcas','almacenes.ver','almacenes.movimientos'];
