app.put('/api/proveedores/:id', authorize('proveedores.editar', 'proveedores.modificar'), (req, res) => {
  const db = readDb(); const id = String(req.params.id); const index = db.proveedores.findIndex((item) => item.id === id);
  if (index < 0) return res.status(404).json({ message: 'Proveedor no encontrado.' });
  const data = providerBody(req.body);
  const incompleto = !data.nombre || (data.tipo === 'empresa' && !data.ruc) || (data.tipo === 'independiente' && !data.telefono);
  if (incompleto) return res.status(400).json({ message: data.tipo === 'empresa' ? 'La empresa y el NIT/RUC son obligatorios.' : 'El nombre y teléfono del proveedor independiente son obligatorios.' });
  if (data.ruc && db.proveedores.some((item, i) => i !== index && String(item.ruc).toLowerCase() === data.ruc.toLowerCase())) return res.status(409).json({ message: 'Ya existe otro proveedor con este NIT/RUC o documento.' });
  const distribuidoresVigentes = new Set(data.agentes.map((agente: { id: string }) => agente.id));
  db.catalogos = db.catalogos.map((producto) => ({ ...producto, asociaciones: Array.isArray(producto.asociaciones) ? (producto.asociaciones as Record<string, unknown>[]).map((asociacion) => String(asociacion.proveedorId) === id && !distribuidoresVigentes.has(String(asociacion.distribuidorId)) ? { ...asociacion, distribuidorId: '' } : asociacion) : [] }));
  db.proveedores[index] = { ...data, id }; writeDb(db); res.json(db.proveedores[index]);
});
