  const telefonoComparable = telefono.replace(/\D/g, '');
  if (db.usuarios.some((item) => item.telefono.replace(/\D/g, '') === telefonoComparable)) return res.status(409).json({ message: `El teléfono “${telefono}” ya está registrado.` });
